// AsCreateCard returns the union data inside the AssistantCard as a CreateCard
func (t AssistantCard) AsCreateCard() (CreateCard, error) {
	var body CreateCard
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromCreateCard overwrites any union data inside the AssistantCard as the provided CreateCard
func (t *AssistantCard) FromCreateCard(v CreateCard) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	b, err = runtime.JSONMerge(b, []byte(`{"kind":"create"}`))
	t.union = b
	return err
}

